// JADES Core API Gateway - Production Ready
// Orchestrates requests to the Python analysis backend.
// ThreatAnalysisRequest defines the structure for incoming analysis requests.
type ThreatAnalysisRequest struct {
Data            json.RawMessage   json:"data"
DataType        string            json:"data_type"
AnalysisLevel   string            json:"analysis_level"
RealTime        bool              json:"real_time"
ContextData     map[string]string json:"context_data"
RequestID       string            json:"request_id"
}
// ThreatAnalysisResponse matches the expected response from the Python backend.
type ThreatAnalysisResponse struct {
AnalysisID      string                 json:"analysis_id"
Timestamp       string                 json:"timestamp"
ThreatLevel     string                 json:"threat_level"
Confidence      float64                json:"confidence"
ProcessingMS    float64                json:"processing_ms"
DetectedThreats []DetectedThreat       json:"detected_threats"
EngineResults   map[string]interface{} json:"raw_engine_outputs"
}
type DetectedThreat struct {
Engine   string json:"engine"
Type     string json:"type"
Severity string json:"severity"
}
var (
pythonBackendURL = ""
httpClient = &http.Client{
Timeout: time.Second * 60,
}
)
// analyzeThreat handles the forwarding of analysis requests to the Python orchestrator.
func analyzeThreat(c *gin.Context) {
var req ThreatAnalysisRequest
if err := c.ShouldBindJSON(&req); err != nil {
c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request body: " + err.Error()})
return
}
req.RequestID = uuid.New().String()
log.Printf("Received analysis request %s for data type %s", req.RequestID, req.DataType)

// Forward the request to the Python backend
jsonReq, err := json.Marshal(req)
if err != nil {
	c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to serialize request"})
	return
}

resp, err := httpClient.Post(pythonBackendURL, "application/json", bytes.NewBuffer(jsonReq))
if err != nil {
	log.Printf("Error calling Python backend for request %s: %v", req.RequestID, err)
	c.JSON(http.StatusServiceUnavailable, gin.H{"error": "Analysis service is unavailable"})
	return
}
defer resp.Body.Close()

// Proxy the response from the Python service
c.DataFromReader(resp.StatusCode, resp.ContentLength, resp.Header.Get("Content-Type"), resp.Body, nil)

}
// healthCheck provides a detailed health status of the gateway and its connections.
