def run_engine_analysis(self, engine_name, payload_json):
    """Runs a specific analysis engine with JSON over stdin/stdout."""
    if self.engines.get(engine_name, {}).get('status') != 'active':
        return {'error': f'Engine {engine_name} is inactive or not found'}

    config = self.engines[engine_name]
    try:
        process = subprocess.Popen([config['executable']], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding='utf-8')
        stdout, stderr = process.communicate(input=payload_json, timeout=30)

        if process.returncode != 0:
            logger.error(f"Error in {engine_name} engine (code {process.returncode}): {stderr}")
            return {'error': f'{engine_name} execution failed', 'details': stderr.strip()}

        return json.loads(stdout)
    except subprocess.TimeoutExpired:
        logger.warning(f"Timeout running {engine_name} analysis.")
        return {'error': f'Timeout for {engine_name} engine'}
    except json.JSONDecodeError:
        logger.error(f"JSON decode error from {engine_name}. Output: {stdout}")
        return {'error': f'Invalid JSON output from {engine_name}'}
    except Exception as e:
        logger.error(f"General error running {engine_name} analysis: {e}")
        return {'error': str(e)}

