def analyze_payload_orchestrator(request_data):
"""Orchestrates a multi-engine, production-grade analysis."""
start_time = time.monotonic()
analysis_id = request_data.get("RequestID", str(uuid.uuid4()))
payload_json = json.dumps(request_data)
engine_results = {}
threads = []
results_lock = threading.Lock()

def run_in_thread(engine_name, data):
    result = engine_manager.run_engine_analysis(engine_name, data)
    with results_lock:
        engine_results[engine_name] = result

for engine in engine_manager.engines:
    if engine_manager.engines[engine]['status'] == 'active':
        thread = threading.Thread(target=run_in_thread, args=(engine, payload_json))
        threads.append(thread)
        thread.start()

for thread in threads:
    thread.join()

# Aggregate results and compute risk
detected_threats = []
confidence_scores = []

for engine, result in engine_results.items():
    if isinstance(result, dict) and not result.get('error') and result.get('is_threat'):
        confidence_scores.append(result.get('confidence', 0.0))
        detected_threats.append({
            "engine": engine,
            "type": result.get("threat_type", "Unknown"),
            "severity": result.get("severity", "Medium"),
            "details": result.get("details", "")
        })

final_confidence = np.mean(confidence_scores) if confidence_scores else 0.0

severity_map = {"Low": 1, "Medium": 3, "High": 5, "Critical": 10}
max_severity_score = max([severity_map.get(t['severity'], 0) for t in detected_threats] or [0])

final_threat_level = "Safe"
if max_severity_score >= 10: final_threat_level = "Critical"
elif max_severity_score >= 5: final_threat_level = "High"
elif max_severity_score >= 3: final_threat_level = "Medium"
elif detected_threats: final_threat_level = "Low"

processing_time = (time.monotonic() - start_time) * 1000

full_report = {
    "analysis_id": analysis_id,
    "timestamp": datetime.utcnow().isoformat() + "Z",
    "threat_level": final_threat_level,
    "confidence": round(final_confidence, 4),
    "processing_ms": round(processing_time, 2),
    "engines_run": list(engine_results.keys()),
    "detected_threats": detected_threats,
    "raw_engine_outputs": engine_results,
}

return full_report

