        .threat_type = "SQL Injection",
        .severity = "Critical",
        .confidence = 0.98,
        .details = "Classic SQL Injection pattern 'UNION SELECT' found.",
    };
}

if (std.mem.contains(u8, payload, "../")) {
     return AnalysisResult{
        .is_threat = true,
        .threat_type = "Path Traversal",
        .severity = "Medium",
        .confidence = 0.85,
        .details = "Path Traversal attempt using '../' sequence.",
    };
}

return AnalysisResult{
