    .threat_type = "None",
    .severity = "Safe",
    .confidence = 0.99,
    .details = "No common web vulnerability patterns detected by Zig engine.",
};

}
pub fn main() !void {
const allocator = std.heap.page_allocator;
var arena = std.heap.ArenaAllocator.init(allocator);
defer arena.deinit();
const arena_allocator = arena.allocator();
// Read entire stdin
const stdin = std.io.getStdIn().reader();
const input = try stdin.readAllAlloc(arena_allocator, 1024 * 1024); // 1MB limit

// Parse input JSON
var json_tree = try std.json.parseFromSlice(AnalysisRequest, arena_allocator, input, .{});
defer json_tree.deinit();

const request = json_tree.value;

// Extract payload for analysis
const payload = switch(request.data) {
    .string => |s| s,
    else => "{}", // Default for non-string data
};

const result = try analyzePayload(payload, arena_allocator);

// Serialize result to JSON and write to stdout
const stdout = std.io.getStdOut().writer();
try std.json.stringify(result, .{}, stdout);

}
