{-# LANGUAGE OverloadedStrings #-}
import qualified Data.ByteString.Lazy.Char8 as LBS
import Data.Aeson
import Data.Text (Text, pack, unpack, isInfixOf, toLower)
data AnalysisResult = AnalysisResult {
is_threat     :: Bool,
threat_type   :: Text,
severity      :: Text,
confidence    :: Double,
details       :: Text
} deriving (Show)
instance ToJSON AnalysisResult where
toJSON res = object [
"is_threat"   .= is_threat res,
"threat_type" .= threat_type res,
"severity"    .= severity res,
"confidence"  .= confidence res,
"details"     .= details res
]
-- Pure functional rule-based analysis for configuration files
analyzeConfig :: Text -> AnalysisResult
analyzeConfig content =
let
lowerContent = toLower content
rules = [ ("Insecure Permissions (e.g., 777)", "critical", 0.98, "chmod 777" isInfixOf lowerContent)
, ("Hardcoded Secret", "high", 0.95, "password =" isInfixOf lowerContent || "api_key =" isInfixOf lowerContent)
, ("Disabled TLS/SSL", "high", 0.90, "ssl_verify = false" isInfixOf lowerContent || "tls_enabled = false" isInfixOf lowerContent)
, ("Debug Mode Enabled in Prod", "medium", 0.85, "debug = true" isInfixOf lowerContent)
]
violations = filter ((_, _, _, violated) -> violated) rules
in
if null violations
then AnalysisResult False "None" "Safe" 0.99 "No configuration vulnerabilities detected by Haskell engine."
else
let (details, severity, confidence, _) = head violations
in AnalysisResult True "Configuration Vulnerability" (pack severity) confidence (pack details)
main :: IO ()
main = do
input <- LBS.getContents
case decode input :: Maybe Value of
Just (Object v) ->
case (v .: "data") >>= (withText "data" pure) of
Success payload -> LBS.putStrLn $ encode (analyzeConfig payload)
_ -> LBS.putStrLn $ encode $ object ["error" .= ("Invalid or missing 'data' field" :: Text)]
_ -> LBS.putStrLn $ encode $ object ["error" .= ("Invalid JSON input" :: Text)]
