proc analyzeLogs(logData: string): AnalysisResult {
var lines = logData.split("\n");
var domain = {0..#lines.size};
var results: [domain] atomic bool;
// Parallel search for suspicious patterns
forall i in domain with (ref results) {
var line = lines[i];
if line.contains("Failed password for root") || line.contains("404") {
results[i].write(true);
} else {
results[i].write(false);
}
